package com.hex.kagune.control.kitchen;

/**
 * Home Living (1.3.40): one dish of the ghoul kitchen ({@link Menu}, generated by {@code tools/kitchen.py}; pure). Its item's registry
 * path, the cookbook chapter it is in, how it is eaten ({@link Kind}), how much it fills (vanilla's nutrition and saturation modifier),
 * how many pieces of ghoul meat a serving holds (each one a piece devoured, {@code GhoulMeat}) and whether there is human meat in it,
 * what it is served in (given back once it is eaten: a bowl, a bottle; null for none), how many its recipe makes, the recipe (the
 * ingredients' item ids, or the one raw cut it is cooked from; null for none: human meat comes off a human), and the effects it gives.
 */
public record Dish(String id, String chapter, Kind kind, int nutrition, float saturation, int ghoulMeat, boolean humanMeat,
                   String container, int makes, Recipe recipe, Effect[] effects) {
    /** How it is eaten: a plate's worth (eaten in the usual time), a bowl's, a drink (drunk), a snack (eaten twice as fast). */
    public enum Kind {
        FOOD, BOWL, DRINK, SNACK
    }

    /** One effect it gives: the effect's key (the kitchen's own, or a vanilla one by its path), for how long (ticks), its amplifier. */
    public record Effect(String key, int ticks, int amplifier) {
    }

    /** What it is made from: shapeless ingredients (crafted), or the one raw cut it is cooked from (a furnace, smoker or campfire). */
    public record Recipe(String[] ingredients, boolean cooking) {
    }

    static Recipe of(String... ingredients) {
        return new Recipe(ingredients, false);
    }

    static Recipe cooked(String raw) {
        return new Recipe(new String[] {raw}, true);
    }

    /** How long it takes to eat or drink (ticks), as vanilla's food: a snack is quick. */
    public int useTicks() {
        return this.kind == Kind.SNACK ? 16 : 32;
    }

    /** True if it can be eaten on a full stomach (a drink, a snack; vanilla's honey and dried kelp are the same). */
    public boolean alwaysEdible() {
        return this.kind == Kind.DRINK || this.kind == Kind.SNACK;
    }

    /** How many fit in a stack: a bowl or a bottle sixteen (vanilla's honey bottles), anything else a full stack. */
    public int stack() {
        return this.container != null ? 16 : 64;
    }

    /** True if a ghoul's growth comes with it ({@code GhoulMeat}): human meat, however cooked, gives none. */
    public boolean feedsGrowth() {
        return this.ghoulMeat > 0;
    }
}
